// Sensor de aproximação: buzzer toca quando algo está a menos de 20 cm
const int trig = 7;
const int echo = 6;
const int buzzer = 8;

void setup() {
  pinMode(trig, OUTPUT);
  pinMode(echo, INPUT);
  pinMode(buzzer, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  // pulso de 10 microssegundos no TRIG
  digitalWrite(trig, LOW);
  delayMicroseconds(2);
  digitalWrite(trig, HIGH);
  delayMicroseconds(10);
  digitalWrite(trig, LOW);

  long duracao = pulseIn(echo, HIGH);       // tempo do eco em microssegundos
  float distancia = duracao * 0.0343 / 2;   // ida e volta, por isso divide por 2

  Serial.print("Distancia: ");
  Serial.print(distancia);
  Serial.println(" cm");

  if (distancia > 0 && distancia < 20) {
    tone(buzzer, 1000);
  } else {
    noTone(buzzer);
  }
  delay(100);
}

