// Alarme em dois níveis: quanto mais perto, mais rápido o bipe
const int trig = 7;
const int echo = 6;
const int buzzer = 8;

void setup() {
  pinMode(trig, OUTPUT);
  pinMode(echo, INPUT);
  Serial.begin(9600);
}

void loop() {
  digitalWrite(trig, LOW);
  delayMicroseconds(2);
  digitalWrite(trig, HIGH);
  delayMicroseconds(10);
  digitalWrite(trig, LOW);

  float distancia = pulseIn(echo, HIGH) * 0.0343 / 2;
  Serial.println(distancia);

  if (distancia > 0 && distancia < 10) {
    tone(buzzer, 2000, 100);
    delay(150);
  } else if (distancia > 0 && distancia < 30) {
    tone(buzzer, 1000, 100);
    delay(400);
  } else {
    delay(100);
  }
}
